module goldbach_checker(\n    input clk,\n    input rst_n,\n    input start,\n    input [5:0] len,\n    input [7:0] arr [0:63],\n    output reg result,\n    output reg done\n);\n\n    // States\n    localparam [2:0]\n        IDLE        = 3'd0,\n        SKIP_WS     = 3'd1,\n        IN_TOKEN    = 3'd2,\n        CHECK_TOKEN = 3'd3,\n        DONE_STATE  = 3'd4,\n        ERROR_STATE = 3'd5;\n\n    reg [2:0] state, next_state;\n\n    reg [5:0] index;\n    reg [2:0] token_count;\n    reg [7:0] token_val;\n    reg [7:0] num1, num2, num3;\n\n    reg [3:0] digit_count;\n    reg leading_zero;\n    reg overflow;\n    reg invalid_char;\n    reg invalid_leading;\n\n    // Prime LUT\n    function automatic is_prime(input [7:0] num);\n        begin\n            if (num < 2) is_prime = 1'b0;\n            else case(num)\n                8'd2,  8'd3,  8'd5,  8'd7,  8'd11, 8'd13, 8'd17, 8'd19, 8'd23, 8'd29,\n                8'd31, 8'd37, 8'd41, 8'd43, 8'd47, 8'd53, 8'd59, 8'd61, 8'd67, 8'd71,\n                8'd73, 8'd79, 8'd83, 8'd89, 8'd97, 8'd101,8'd103,8'd107,8'd109,8'd113,\n                8'd127,8'd131,8'd137,8'd139,8'd149,8'd151,8'd157,8'd163,8'd167,8'd173,\n                8'd179,8'd181,8'd191,8'd193,8'd197,8'd199,8'd211,8'd223,8'd227,8'd229,\n                8'd233,8'd239,8'd241,8'd251: is_prime = 1'b1;\n                default: is_prime = 1'b0;\n            endcase\n        end\n    endfunction\n\n    // FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            index <= 6'd0;\n            token_count <= 3'd0;\n            token_val <= 8'd0;\n            num1 <= 8'd0;\n            num2 <= 8'd0;\n            num3 <= 8'd0;\n            digit_count <= 4'd0;\n            leading_zero <= 1'b0;\n            overflow <= 1'b0;\n            invalid_char <= 1'b0;\n            invalid_leading <= 1'b0;\n            result <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SKIP_WS;\n                        index <= 6'd0;\n                        token_count <= 3'd0;\n                        token_val <= 8'd0;\n                        num1 <= 8'd0;\n                        num2 <= 8'd0;\n                        num3 <= 8'd0;\n                        digit_count <= 4'd0;\n                        leading_zero <= 1'b0;\n                        overflow <= 1'b0;\n                        invalid_char <= 1'b0;\n                        invalid_leading <= 1'b0;\n                    end\n                end\n\n                SKIP_WS: begin\n                    if (index >= len) begin\n                        if (token_count == 3'd3) state <= DONE_STATE;\n                        else state <= ERROR_STATE;\n                    end else begin\n                        case(arr[index])\n                            8'h20, 8'h09, 8'h0D, 8'h0A: index <= index + 1;  // WS\n                            default: begin\n                                if (arr[index] >= 8'h30 && arr[index] <= 8'h39) begin\n                                    digit_count <= 1;\n                                    token_val <= arr[index] - 8'h30;\n                                    leading_zero <= (arr[index] == 8'h30);\n                                    state <= IN_TOKEN;\n                                    index <= index + 1;\n                                end else begin\n                                    invalid_char <= 1'b1;\n                                    state <= ERROR_STATE;\n                                end\n                            end\n                        endcase\n                    end\n                end\n\n                IN_TOKEN: begin\n                    if (index >= len) begin\n                        if (leading_zero && digit_count > 1) invalid_leading <= 1'b1;\n                        if (overflow || token_val > 8'd255) state <= ERROR_STATE;\n                        else state <= CHECK_TOKEN;\n                    end else begin\n                        case(arr[index])\n                            8'h20, 8'h09, 8'h0D, 8'h0A: begin\n                                if (leading_zero && digit_count > 1) invalid_leading <= 1'b1;\n                                if (overflow || token_val > 8'd255) state <= ERROR_STATE;\n                                else state <= CHECK_TOKEN;\n                            end\n                            8'h30, 8'h31, 8'h32, 8'h33, 8'h34, \n                            8'h35, 8'h36, 8'h37, 8'h38, 8'h39: begin\n                                digit_count <= digit_count + 1;\n                                if (digit_count >= 4'd3) overflow <= 1'b1;\n                                else if (leading_zero) invalid_leading <= 1'b1;\n                                else begin\n                                    token_val <= token_val * 8'd10 + (arr[index] - 8'h30);\n                                    if (token_val > 8'd25) overflow <= 1'b1;\n                                end\n                                index <= index + 1;\n                            end\n                            default: invalid_char <= 1'b1;\n                        endcase\n                        if (invalid_leading || overflow) state <= ERROR_STATE;\n                    end\n                end\n\n                CHECK_TOKEN: begin\n                    case(token_count)\n                        3'd0: num1 <= token_val;\n                        3'd1: num2 <= token_val;\n                        3'd2: num3 <= token_val;\n                    endcase\n                    token_count <= token_count + 1;\n                    token_val <= 8'd0;\n                    digit_count <= 4'd0;\n                    leading_zero <= 1'b0;\n                    overflow <= 1'b0;\n                    state <= SKIP_WS;\n                end\n\n                DONE_STATE: begin\n                    if (num1 > 8'd3 && num1 <= 8'd255 && num1[0] == 0 &&\n                        num2 > 8'd0 && num3 > 8'd0 &&\n                        is_prime(num2) && is_prime(num3) &&\n                        (num2 + num3) == num1) result <= 1'b1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                ERROR_STATE: begin\n                    result <= 1'b0;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule